class EnvVarCheck
{
    void CheckFlag()
    {
        // In .NET 9, empty env vars are no longer treated as unset.
        // GetEnvironmentVariable now returns "" instead of null for export MY_FLAG="".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        else if (val.Length == 0)
        {
            Console.WriteLine("MY_FLAG explicitly empty");
        }
    }
}

